import { AddTodo } from './components/AddTodo.jsx'
import { TodoList } from './components/TodoList.jsx'
import { useTodos } from './hooks/useTodos.js'

export function App({ initial }) {
  const { todos, add, toggle, remove, clearCompleted } = useTodos(initial)
  const left = todos.filter((todo) => !todo.done).length

  return (
    <main>
      <h1>Todos</h1>
      <AddTodo onAdd={add} />
      <TodoList todos={todos} onToggle={toggle} onRemove={remove} />
      {todos.length > 0 && (
        <div className="footer">
          <span>{left === 1 ? '1 item left' : `${left} items left`}</span>
          <button type="button" onClick={clearCompleted} disabled={left === todos.length}>
            Clear completed
          </button>
        </div>
      )}
    </main>
  )
}

